class Solution { public int maxPalindromesAfterOperations(String[] words){int[] frequency=new int[26],lengths=new int[words.length];for(int index=0;index<words.length;index++){lengths[index]=words[index].length();for(char letter:words[index].toCharArray())frequency[letter-'a']++;}int pairs=0;for(int count:frequency)pairs+=count/2;Arrays.sort(lengths);int answer=0;for(int length:lengths){int need=length/2;if(pairs<need)break;pairs-=need;answer++;}return answer;} }
